// Seis mensajes inventados, como los que podría recibir una organización de Santa Cruz.
const mensajes = [
  '¿A qué hora abren el punto de reciclaje del barrio el sábado?',
  'Hace dos semanas que no pasa el camión de la basura por mi calle y nadie responde.',
  'Propongo que hagamos una feria de trueque de ropa en la plaza una vez por mes.',
  '¿Cómo me inscribo al taller de compostaje?',
  'Me cobraron dos veces la inscripción al taller y todavía no me devolvieron la plata.',
  'Sería bueno tener un mapa con los puntos de agua potable de la zona.',
];
return mensajes.map((mensaje) => ({ json: { mensaje, origen: 'ejemplo' } }));

